// @ts-check
import { defineConfig } from 'astro/config';

// https://astro.build/config
export default defineConfig({
  // Alamat situsmu nanti. Dipakai untuk canonical, Open Graph, RSS, dan sitemap.
  site: 'https://USERNAME.github.io',
  // Nama repositori GitHub-mu, diawali garis miring.
  base: '/blog-astro',
});

// Menambahkan `base` dari astro.config.mjs ke tautan internal.
// url('/tentang/') -> '/blog-astro/tentang/'
const base = import.meta.env.BASE_URL.replace(/\/$/, '');

export const url = (path: string) => base + path;

/* Warna terang (bawaan) */
:root {
  --latar: #fbfaf7;
  --teks: #1d1d1b;
  --redup: #5c5b57;
  --aksen: #2f6b3a;
  --garis: #e2e0d9;
  --kode: #f0eee8;
  color-scheme: light;
}

/* Warna gelap, aktif saat <html data-tema="gelap"> */
:root[data-tema='gelap'] {
  --latar: #141513;
  --teks: #ecebe6;
  --redup: #a9a8a1;
  --aksen: #9fd39f;
  --garis: #33342f;
  --kode: #1f201d;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--latar);
  color: var(--teks);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  /* 17px di HP, naik pelan sampai 19px di layar lebar */
  font-size: clamp(1.0625rem, 1rem + 0.3vw, 1.1875rem);
  line-height: 1.7;
}

main,
.kepala,
.kaki {
  max-width: 42rem; /* sekitar 65-75 karakter per baris */
  margin-inline: auto;
  padding-inline: 1rem;
}

main {
  padding-block: 1.5rem 3rem;
}

h1,
h2,
h3 {
  line-height: 1.25;
  text-wrap: balance;
}

h1 {
  font-size: clamp(1.75rem, 1.4rem + 1.5vw, 2.5rem);
}

a {
  color: var(--aksen);
  text-underline-offset: 0.2em;
}

:focus-visible {
  outline: 3px solid var(--aksen);
  outline-offset: 2px;
}

img {
  max-width: 100%;
  height: auto;
}

/* Kode panjang digeser di dalam kotaknya, bukan seluruh halaman */
pre {
  overflow-x: auto;
  padding: 1rem;
  border-radius: 0.5rem;
  font-size: 0.9em;
}

code {
  font-family: ui-monospace, 'Cascadia Code', Menlo, monospace;
}

:not(pre) > code {
  background: var(--kode);
  padding: 0.1em 0.35em;
  border-radius: 0.25rem;
}

/* Tautan panjang tidak merusak tata letak di layar sempit */
.prosa {
  overflow-wrap: anywhere;
}

.lewati {
  position: absolute;
  left: -999px;
}

.lewati:focus {
  left: 1rem;
  top: 1rem;
  background: var(--latar);
  padding: 0.5rem 1rem;
}

.meta {
  color: var(--redup);
  font-size: 0.9em;
}

.kepala {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1rem;
  padding-block: 1rem;
  border-bottom: 1px solid var(--garis);
}

.logo {
  font-weight: 700;
  color: var(--teks);
  text-decoration: none;
  margin-right: auto;
}

.kepala ul {
  display: flex;
  gap: 1rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.kepala a[aria-current='page'] {
  font-weight: 700;
}

.tombol-tema {
  min-width: 2.75rem;
  min-height: 2.75rem;
  border: 1px solid var(--garis);
  border-radius: 999px;
  background: transparent;
  color: var(--teks);
  cursor: pointer;
}

.daftar {
  list-style: none;
  padding: 0;
}

.daftar li + li {
  border-top: 1px solid var(--garis);
}

.daftar h2 {
  font-size: 1.3rem;
  margin-bottom: 0.25rem;
}

.daftar h2 a {
  text-decoration: none;
}

.daftar h2 a:hover {
  text-decoration: underline;
}

.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0;
  list-style: none;
}

.tag-list a {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border: 1px solid var(--garis);
  border-radius: 999px;
  text-decoration: none;
}

.foto {
  border-radius: 50%;
}

.kaki {
  padding-block: 2rem;
  border-top: 1px solid var(--garis);
  color: var(--redup);
  font-size: 0.9em;
}

