import ThemeToggle from './ThemeToggle.astro';
import { url } from '../lib/url';

const menu = [
  { href: url('/'), label: 'Tulisan' },
  { href: url('/tag/'), label: 'Tag' },
  { href: url('/tentang/'), label: 'Tentang' },
];
const sekarang = Astro.url.pathname;
---

<header class="kepala">
  <a class="logo" href={url('/')}>Blog Rani</a>
  <nav aria-label="Utama">
    <ul>
      {
        menu.map((m) => (
          <li>
            <a href={m.href} aria-current={sekarang === m.href ? 'page' : undefined}>
              {m.label}
            </a>
          </li>
        ))
      }
    </ul>
  </nav>
  <ThemeToggle />
</header>

