import '../styles/global.css';
import Header from '../components/Header.astro';
import { url } from '../lib/url';

interface Props {
  title: string;
  description: string;
  type?: 'website' | 'article';
}

const { title, description, type = 'website' } = Astro.props;
const NAMA_SITUS = 'Blog Rani';
const judul = title === NAMA_SITUS ? title : `${title} | ${NAMA_SITUS}`;
const canonical = new URL(Astro.url.pathname, Astro.site);
const gambarOg = new URL(url('/og.png'), Astro.site);
---

<!doctype html>
<html lang="id">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{judul}</title>
    <meta name="description" content={description} />
    <link rel="canonical" href={canonical} />

    <!-- Open Graph: tampilan saat tautan dibagikan di WhatsApp, LinkedIn, X -->
    <meta property="og:type" content={type} />
    <meta property="og:site_name" content={NAMA_SITUS} />
    <meta property="og:title" content={title} />
    <meta property="og:description" content={description} />
    <meta property="og:url" content={canonical} />
    <meta property="og:image" content={gambarOg} />
    <meta property="og:locale" content="id_ID" />
    <meta name="twitter:card" content="summary_large_image" />

    <link rel="icon" type="image/svg+xml" href={url('/favicon.svg')} />
    <link rel="alternate" type="application/rss+xml" title={NAMA_SITUS} href={new URL(url('/rss.xml'), Astro.site)} />
    <link rel="sitemap" href={url('/sitemap-index.xml')} />

    <!-- Dijalankan sebelum halaman digambar, jadi warna tidak berkedip -->
    <script is:inline>
      const tersimpan = localStorage.getItem('tema');
      const sukaGelap = matchMedia('(prefers-color-scheme: dark)').matches;
      document.documentElement.dataset.tema = tersimpan ?? (sukaGelap ? 'gelap' : 'terang');
    </script>
  </head>
  <body>
    <a class="lewati" href="#isi">Langsung ke isi</a>
    <Header />
    <main id="isi">
      <slot />
    </main>
    <footer class="kaki">
      <p>© {new Date().getFullYear()} Rani. <a href={url('/rss.xml')}>RSS</a></p>
    </footer>
  </body>
</html>

import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

const blog = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/blog' }),
  schema: z.object({
    title: z.string().max(80),
    date: z.coerce.date(),
    description: z.string().max(160),
    tags: z.array(z.string().regex(/^[a-z0-9-]+$/, 'Tag pakai huruf kecil, angka, dan tanda -')).default([]),
    draft: z.boolean().default(false),
  }),
});

export const collections = { blog };

import { getCollection, type CollectionEntry } from 'astro:content';

export type Tulisan = CollectionEntry<'blog'>;

// Semua tulisan, terbaru di atas. Draf hanya tampil saat `npm run dev`.
export async function ambilTulisan(): Promise<Tulisan[]> {
  const semua = await getCollection('blog', ({ data }) => import.meta.env.DEV || !data.draft);
  return semua.sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());
}

// Rata-rata orang membaca sekitar 200 kata per menit.
export function waktuBaca(teks = ''): number {
  const kata = teks.split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(kata / 200));
}

export function formatTanggal(tanggal: Date): string {
  return tanggal.toLocaleDateString('id-ID', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

