import { formatTanggal, waktuBaca, type Tulisan } from '../lib/tulisan';
import { url } from '../lib/url';

interface Props {
  tulisan: Tulisan[];
}

const { tulisan } = Astro.props;
---

<ul class="daftar">
  {
    tulisan.map((t) => (
      <li>
        <article>
          <h2>
            <a href={url(`/blog/${t.id}/`)}>{t.data.title}</a>
          </h2>
          <p class="meta">
            <time datetime={t.data.date.toISOString()}>{formatTanggal(t.data.date)}</time> ·{' '}
            {waktuBaca(t.body)} menit baca
            {t.data.draft && <strong> · DRAF</strong>}
          </p>
          <p>{t.data.description}</p>
        </article>
      </li>
    ))
  }
</ul>

