import BaseLayout from './BaseLayout.astro';
import { formatTanggal, waktuBaca, type Tulisan } from '../lib/tulisan';
import { url } from '../lib/url';

interface Props {
  tulisan: Tulisan;
}

const { data, body } = Astro.props.tulisan;
---

<BaseLayout title={data.title} description={data.description} type="article">
  <article>
    <header>
      <h1>{data.title}</h1>
      <p class="meta">
        <time datetime={data.date.toISOString()}>{formatTanggal(data.date)}</time> ·{' '}
        {waktuBaca(body)} menit baca
      </p>
      <ul class="tag-list" aria-label="Tag">
        {
          data.tags.map((tag) => (
            <li>
              <a href={url(`/tag/${tag}/`)}>#{tag}</a>
            </li>
          ))
        }
      </ul>
    </header>
    <div class="prosa">
      <slot />
    </div>
  </article>
  <p><a href={url('/')}>← Semua tulisan</a></p>
</BaseLayout>

