import { render } from 'astro:content';
import PostLayout from '../../layouts/PostLayout.astro';
import { ambilTulisan } from '../../lib/tulisan';

export async function getStaticPaths() {
  const semua = await ambilTulisan();
  return semua.map((tulisan) => ({
    params: { id: tulisan.id },
    props: { tulisan },
  }));
}

const { tulisan } = Astro.props;
const { Content } = await render(tulisan);
---

<PostLayout tulisan={tulisan}>
  <Content />
</PostLayout>

---
import BaseLayout from '../../layouts/BaseLayout.astro';
import DaftarTulisan from '../../components/DaftarTulisan.astro';
import { ambilTulisan } from '../../lib/tulisan';
import { url } from '../../lib/url';

export async function getStaticPaths() {
  const semua = await ambilTulisan();
  const semuaTag = [...new Set(semua.flatMap((t) => t.data.tags))];
  return semuaTag.map((tag) => ({
    params: { tag },
    props: { tulisan: semua.filter((t) => t.data.tags.includes(tag)) },
  }));
}

const { tag } = Astro.params;
const { tulisan } = Astro.props;
---

<BaseLayout title={`Tag #${tag}`} description={`Semua tulisan dengan tag ${tag}.`}>
  <h1>Tag #{tag}</h1>
  <p class="meta">{tulisan.length} tulisan</p>
  <DaftarTulisan tulisan={tulisan} />
  <p><a href={url('/tag/')}>Lihat semua tag</a></p>
</BaseLayout>

