import BaseLayout from '../../layouts/BaseLayout.astro';
import { ambilTulisan } from '../../lib/tulisan';
import { url } from '../../lib/url';

const semua = await ambilTulisan();
const jumlah = new Map<string, number>();
for (const tag of semua.flatMap((t) => t.data.tags)) {
  jumlah.set(tag, (jumlah.get(tag) ?? 0) + 1);
}
const daftarTag = [...jumlah].sort((a, b) => a[0].localeCompare(b[0]));
---

<BaseLayout title="Semua tag" description="Jelajahi tulisan berdasarkan topik.">
  <h1>Semua tag</h1>
  <ul class="tag-list">
    {
      daftarTag.map(([tag, n]) => (
        <li>
          <a href={url(`/tag/${tag}/`)}>
            #{tag} ({n})
          </a>
        </li>
      ))
    }
  </ul>
</BaseLayout>

// @ts-check
import { defineConfig } from 'astro/config';

import sitemap from '@astrojs/sitemap';

// https://astro.build/config
export default defineConfig({
  // Alamat situsmu nanti. Dipakai untuk canonical, Open Graph, RSS, dan sitemap.
  site: 'https://USERNAME.github.io',

  // Nama repositori GitHub-mu, diawali garis miring.
  base: '/blog-astro',

  integrations: [sitemap()],
});

import rss from '@astrojs/rss';
import type { APIContext } from 'astro';
import { ambilTulisan } from '../lib/tulisan';
import { url } from '../lib/url';

export async function GET(context: APIContext) {
  const tulisan = await ambilTulisan();
  const beranda = new URL(url('/'), context.site);
  return rss({
    title: 'Blog Rani',
    description: 'Catatan belajar web development Rani.',
    site: beranda,
    xmlns: { atom: 'http://www.w3.org/2005/Atom' },
    items: tulisan.map((t) => ({
      title: t.data.title,
      description: t.data.description,
      pubDate: t.data.date,
      categories: t.data.tags,
      link: url(`/blog/${t.id}/`),
    })),
    customData: `<language>id</language><atom:link href="${new URL('rss.xml', beranda)}" rel="self" type="application/rss+xml"/>`,
  });
}

